<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue';
import {views,duration,fresh,advance,snap,pause,resume,viewX,inFrame} from './quick-engine';
const state=ref(fresh()),reduced=ref(false),best=ref(0);let frame=0,last=0;
const activeViews=computed(()=>views.map((v,i)=>({...v,i,x:viewX(i,state.value.time)})).filter(v=>v.x>-160&&v.x<1160));
const region=computed(()=>views[Math.min(9,Math.floor(state.value.time/4.3))].region);
const ready=computed(()=>inFrame(state.value)!==undefined);
function start(){state.value=fresh('playing');last=performance.now();}
function take(){if(state.value.phase==='demo')start();else if(state.value.phase==='playing')state.value=snap(state.value);}
function toggle(){state.value=state.value.phase==='paused'?resume(state.value):pause(state.value);last=performance.now();}
function freeze(){state.value=pause(state.value);}
function keys(e:KeyboardEvent){if((e.target as HTMLElement)?.closest('input,textarea,select'))return;if(e.code==='KeyP'||e.code==='Escape'){e.preventDefault();if(!e.repeat)toggle();return;}if((e.target as HTMLElement)?.closest('button,a'))return;if(e.code==='Space'){e.preventDefault();if(!e.repeat)take();}}
function tick(now:number){const dt=last?(now-last)/1000:0;last=now;const previous=state.value.phase;if(!(reduced.value&&previous==='demo'))state.value=advance(state.value,dt);if(previous==='playing'&&state.value.phase==='done'){best.value=Math.max(best.value,state.value.score);try{localStorage.setItem('canada-camera-best',String(best.value));}catch{}}frame=requestAnimationFrame(tick);}
onMounted(()=>{reduced.value=matchMedia('(prefers-reduced-motion: reduce)').matches;try{best.value=Number(localStorage.getItem('canada-camera-best'))||0;}catch{}document.addEventListener('keydown',keys);window.addEventListener('blur',freeze);document.addEventListener('visibilitychange',freeze);frame=requestAnimationFrame(tick);});
onUnmounted(()=>{cancelAnimationFrame(frame);document.removeEventListener('keydown',keys);window.removeEventListener('blur',freeze);document.removeEventListener('visibilitychange',freeze);});
</script>
<template>
 <main class="camera-game">
  <header class="camera-top"><a href="https://funapps.ca/">FunApps</a><h1>Postcards from Canada</h1><a href="?mode=planner">Trip planner</a></header>
  <div class="camera-hud"><span class="place">{{region}}</span><span><b>{{state.cards.length}}</b> / 10 postcards</span><span><b>{{state.score}}</b> points</span><span>{{Math.ceil(duration-state.time)}}s</span><button @click="toggle" :disabled="state.phase==='demo'||state.phase==='done'">{{state.phase==='paused'?'Resume':'Pause'}}</button></div>
  <section class="camera-scene" aria-label="Moving Canadian scenery. Photograph landmarks as they enter the central camera frame." @pointerdown="take">
   <svg viewBox="0 0 1000 580" preserveAspectRatio="xMidYMid slice" aria-hidden="true">
    <defs><linearGradient id="sky" x2="0" y2="1"><stop stop-color="#58b8dc"/><stop offset="1" stop-color="#d8f2e3"/></linearGradient><linearGradient id="water" x2="0" y2="1"><stop stop-color="#2286a0"/><stop offset="1" stop-color="#155a73"/></linearGradient></defs>
    <rect width="1000" height="580" fill="url(#sky)"/><circle cx="830" cy="95" r="42" fill="#ffe79c"/>
    <g fill="white" opacity=".7" :transform="`translate(${-state.time*4%250} 0)`"><path d="M60 90a30 30 0 0160-8 25 25 0 0140 8zM400 66a35 35 0 0168-5 24 24 0 0136 5zM900 128a30 30 0 0160-8 25 25 0 0140 8z"/></g>
    <path d="M-50 365L150 150 295 335 420 105 650 365 840 180 1080 365" fill="#568d9b"/><path d="M95 210L150 150 205 220 163 204 140 214zM357 180L420 105 490 182 438 162 406 177z" fill="#f4fbf7"/><path d="M0 310Q220 245 430 333T1000 300V580H0" fill="#317d68"/>
    <rect y="350" width="1000" height="230" fill="url(#water)"/>
    <g v-for="v in activeViews" :key="v.i" :transform="`translate(${v.x},335)`" :opacity="state.cards.includes(v.i)?.5:1">
     <g v-if="v.kind==='mountain'"><path d="M-100 20L0-190 100 20Z" fill="#315c73"/><path d="M-35-120L0-190 38-118 9-136-9-119Z" fill="white"/></g>
     <g v-else-if="v.kind==='prairie'"><path d="M-55 20V-130L0-168 55-130V20Z" fill="#cb5941"/><rect x="-20" y="-110" width="40" height="100" fill="#7d3e3a"/><path d="M-65-125L0-175 65-125" stroke="#fff1c5" stroke-width="13" fill="none"/></g>
     <g v-else-if="v.kind==='bison'" fill="#653f32"><ellipse cy="-24" rx="65" ry="38"/><circle cx="-55" cy="-36" r="31"/><path d="M-72-58L-85-76-82-45M-35-7V30H-48V-7M35-7V30H48V-7"/><circle cx="-67" cy="-42" r="4" fill="white"/></g>
     <g v-else-if="v.kind==='city'" fill="#29485d"><path d="M-60 20V-75H-20V20M10 20V-135H45V20M65 20V-55H90V20"/><path d="M-2 20V-205" stroke="#29485d" stroke-width="8"/><ellipse cx="-2" cy="-142" rx="22" ry="9"/><g fill="#fbd879"><rect x="-52" y="-60" width="14" height="22"/><rect x="20" y="-110" width="12" height="24"/></g></g>
     <g v-else-if="v.kind==='village'"><g v-for="(c,j) in ['#e86b4e','#e5b348','#4b99b3']" :transform="`translate(${j*58-90} 0)`"><rect y="-90" width="54" height="110" :fill="c"/><path d="M-6-90L27-122 61-90" fill="#283e55"/><rect x="9" y="-66" width="12" height="20" fill="#fff6d5"/><rect x="32" y="-66" width="12" height="20" fill="#fff6d5"/><rect x="20" y="-20" width="15" height="40" fill="#304c5a"/></g></g>
     <g v-else-if="v.kind==='bridge'"><rect x="-100" y="-55" width="200" height="70" fill="#bb4d3c"/><path d="M-115-55L0-95 115-55" fill="#3b4d56"/><path d="M-85-40L-50 0-15-40 20 0 55-40 90 0" fill="none" stroke="#f6c090" stroke-width="9"/><path d="M-75 15V50M75 15V50" stroke="#6c7167" stroke-width="20"/></g>
     <g v-else-if="v.kind==='lighthouse'"><path d="M-30 20L-20-145H20L30 20Z" fill="#fff9e9"/><path d="M-25-65H25L27-20H-27Z" fill="#dc5e47"/><rect x="-27" y="-173" width="54" height="30" fill="#ffdf76"/><path d="M-37-174L0-199 37-174Z" fill="#cd4e3c"/><path d="M-40-142H40" stroke="#354c57" stroke-width="8"/></g>
     <g v-else><path d="M-120 20Q-60-40 0-20T120 20" fill="#e7bd76"/><path d="M-80 0L-40-100 0 0M10 0L55-130 100 0" fill="#164e4c"/><circle v-if="v.kind==='coast'" cy="-100" r="45" fill="#ffbd67"/></g>
     <rect x="-128" y="45" width="256" height="38" rx="19" fill="#0c344a"/><text y="70" text-anchor="middle" fill="white" font-size="19" font-weight="700">{{state.cards.includes(v.i)?'✓ ':''}}{{v.name}}</text>
    </g>
    <path d="M0 485Q500 390 1000 485V580H0Z" fill="#dbb87b"/><path d="M0 520Q500 420 1000 520" fill="none" stroke="#3e4c5e" stroke-width="82"/><path :stroke-dashoffset="-state.time*130" d="M0 520Q500 420 1000 520" fill="none" stroke="#fff2c8" stroke-width="5" stroke-dasharray="34 38"/>
    <g :transform="`translate(170,${467+(reduced?0:Math.sin(state.time*7)*2)})`"><rect x="-65" y="-58" width="130" height="64" rx="16" fill="#f07b4f"/><path d="M-47-45H10V-18H-47ZM22-45H42L54-18H22Z" fill="#bde5e6"/><rect x="-63" y="-12" width="126" height="12" fill="#ffe4bd"/><circle cx="-38" cy="7" r="15" fill="#283d4d"/><circle cx="39" cy="7" r="15" fill="#283d4d"/><circle cx="-38" cy="7" r="6" fill="#c6d6d6"/><circle cx="39" cy="7" r="6" fill="#c6d6d6"/></g>
    <g :stroke="ready?'#ffef7d':'white'" stroke-width="6" fill="none"><path d="M410 195V155H450M550 155H590V195M410 330V370H450M550 370H590V330"/><circle v-if="ready" cx="500" cy="265" r="100" stroke-dasharray="8 10" opacity=".4"/></g>
    <text x="500" y="127" text-anchor="middle" fill="#102e43" font-size="21" font-weight="800">{{ready?'SNAP NOW!':'GET THE VIEW IN HERE'}}</text>
    <rect v-if="state.flash>0&&!reduced" width="1000" height="580" fill="white" :opacity="state.flash*2"/>
   </svg>
   <div v-if="state.phase==='demo'" class="camera-start"><span>ONE VAN. TEN VIEWS.</span><h2>A whole country<br>in your camera.</h2><p>Tap SNAP when a view enters the frame.</p><button @pointerdown.stop @click="start">Let’s roll</button></div>
   <div v-if="state.phase==='paused'" class="camera-overlay"><h2>Taking a breather.</h2><button @pointerdown.stop @click="toggle">Resume trip</button></div>
   <div v-if="state.phase==='done'" class="camera-overlay"><span>PACIFIC TO ATLANTIC</span><h2>Wish you were here.</h2><p>{{state.cards.length}} postcards · {{state.score}} points</p><p class="best">Best: {{best}}</p><div class="camera-stamps"><span v-for="i in state.cards" :key="i">{{views[i].name}}</span></div><button @pointerdown.stop @click="start">Road trip again</button></div>
  </section>
  <footer class="camera-controls"><div><b>{{state.phase==='demo'?'Point. Snap. Keep rolling.':state.message}}</b><small>Space or tap to snap · P to pause</small></div><button class="snap-button" :class="{ready}" :disabled="state.phase==='paused'||state.phase==='done'" @click="take">◎ SNAP</button></footer>
  <div class="camera-progress" aria-label="Trip progress" role="progressbar" :aria-valuenow="Math.floor(state.time)" :aria-valuemax="duration" aria-valuemin="0"><i :style="{width:state.time/duration*100+'%'}"/></div>
 </main>
</template>
<style>
*{box-sizing:border-box}body{margin:0;background:#102e43;color:#f7fbfa;font-family:system-ui,sans-serif}button,a{-webkit-tap-highlight-color:transparent}button{font:inherit;cursor:pointer}button:focus-visible,a:focus-visible{outline:3px solid #ffe369;outline-offset:4px}.camera-game{height:100svh;min-height:560px;display:flex;flex-direction:column;max-width:1800px;margin:auto}.camera-top{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:13px 24px;background:#0c2638}.camera-top a{color:#c0dfe4;font-size:14px;text-decoration:none}.camera-top h1{font-size:clamp(16px,2.4vw,25px);margin:0}.camera-hud{display:flex;align-items:center;gap:25px;padding:10px 24px;background:#174359;font-size:16px}.camera-hud .place{margin-right:auto;font-weight:750;color:#ffe395}.camera-hud button{background:none;color:white;border:1px solid #6a8c9c;padding:7px 12px;border-radius:8px}.camera-hud button:disabled{opacity:.4;cursor:default}.camera-scene{flex:1;min-height:280px;position:relative;overflow:hidden;touch-action:manipulation}.camera-scene>svg{display:block;width:100%;height:100%;position:absolute;inset:0}.camera-start{position:absolute;left:3%;top:6%;max-width:340px;padding:24px;border-radius:22px;background:#102e43ec;box-shadow:0 14px 40px #081e3533}.camera-start span,.camera-overlay>span{font-size:13px;letter-spacing:.15em;color:#ffe395}.camera-start h2{font-size:clamp(28px,3vw,44px);line-height:1.04;margin:14px 0}.camera-start p{line-height:1.4}.camera-start button,.camera-overlay button{border:0;border-radius:12px;padding:15px 30px;background:#ffdc78;color:#163347;font-weight:850;font-size:20px}.camera-overlay{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;flex-direction:column;background:#0e2e43e8;text-align:center;padding:22px}.camera-overlay h2{font-size:clamp(32px,5vw,60px);margin:10px}.camera-overlay p{font-size:22px;margin:10px}.camera-overlay .best{font-size:15px;color:#b4d8df}.camera-stamps{display:flex;flex-wrap:wrap;justify-content:center;gap:7px;max-width:650px;margin:15px}.camera-stamps span{border:1px dashed #a3c8d4;padding:8px;font-size:14px}.camera-controls{display:flex;align-items:center;justify-content:space-between;gap:15px;padding:14px 24px}.camera-controls b{font-size:16px}.camera-controls small{display:block;color:#add1da;margin-top:5px;font-size:14px}.snap-button{flex-shrink:0;background:#f6fcf8;color:#163347;border:0;border-radius:14px;min-width:170px;padding:17px;font-size:24px;font-weight:850}.snap-button.ready{background:#ffdf75;box-shadow:0 0 25px #ffdf7550}.snap-button:disabled{opacity:.5}.camera-progress{height:5px;background:#294b5d}.camera-progress i{display:block;height:100%;background:#ffdc78}@media(max-width:650px){.camera-top{padding:10px 12px}.camera-top a{font-size:12px}.camera-hud{gap:12px;flex-wrap:wrap;font-size:14px;padding:8px 12px}.camera-hud .place{width:100%;margin:0}.camera-hud button{margin-left:auto}.camera-scene>svg{width:100%;height:100%;object-fit:cover}.camera-start{left:12px;top:12px;padding:18px;max-width:235px}.camera-start h2{font-size:28px}.camera-start p{font-size:14px}.camera-start button{font-size:18px;padding:12px 22px}.camera-controls{padding:10px 12px}.camera-controls b{font-size:14px}.camera-controls small{font-size:12px}.snap-button{min-width:120px;font-size:20px;padding:14px}.camera-game{min-height:600px}.camera-stamps span{font-size:12px;padding:5px}}
</style>
